<?php
namespace qqworld_collector\module\collecting\magics; class tmall extends magic_collecting { var $guid = 'tmall'; public function includes() { require __DIR__ . DIRECTORY_SEPARATOR . 'class.parse_tmall_product.php'; } public function magic_collecting_before($results, $post, $args) { if (class_exists('woocommerce')) { $source_link = $post['meta_input']['source-link']; $parser = new parse_tmall_product; $product = $parser->parse($source_link, $args); $data = array('product' => $product); $results = apply_filters( 'qqworld-collector-woocommerce-create-product', $results, $data ); } else { $results['success'] = 0; $results['msg'] = __('You have not installed WooCommerce yet.', $this->text_domain); } return $results; } public function magic_collecting_after($results, $post, $post_id, $args) { $source_link = $post['meta_input']['source-link']; $source_link = preg_replace('/(\?id=\d*).*/i', '$1', $source_link); update_post_meta($post_id, 'source-link', $source_link); return $results; } } new tmall; ?>